resources.afterResponseScript:
const status = insomnia.response.code;
let body = {};
try {
  body = insomnia.response.json();
} catch (e) {
  body = {};
}

insomnia.test('Курьер создан: статус 201', () => {
  insomnia.expect(status).to.equal(201);
});

if (status === 201) {
  insomnia.test('В ответе передан courierId', () => {
    insomnia.expect(body).to.have.property('courierId');
  });

  if (body.courierId) {
    insomnia.environment.set('courierId', body.courierId);
  }
}

const status = insomnia.response.code;
let body = null;
try {
  body = insomnia.response.json();
} catch (e) {
  body = null;
}

insomnia.test('Список курьеров получен: статус 200', () => {
  insomnia.expect(status).to.equal(200);
});

insomnia.test('Ответ — массив', () => {
  insomnia.expect(body).to.be.an('array');
});

insomnia.test('Каждый курьер содержит id, name, location', () => {
  (body || []).forEach((courier) => {
    insomnia.expect(courier).to.have.property('id');
    insomnia.expect(courier).to.have.property('name');
    insomnia.expect(courier).to.have.property('location');
  });
});

const status = insomnia.response.code;
let body = {};
try {
  body = insomnia.response.json();
} catch (e) {
  body = {};
}

insomnia.test('Заказ создан: статус 201', () => {
  insomnia.expect(status).to.equal(201);
});

if (status === 201) {
  insomnia.test('В ответе передан orderId', () => {
    insomnia.expect(body).to.have.property('orderId');
  });

  if (body.orderId) {
    insomnia.environment.set('orderId', body.orderId);
  }
}

const status = insomnia.response.code;
let body = null;
try {
  body = insomnia.response.json();
} catch (e) {
  body = null;
}

insomnia.test('Список активных заказов получен: статус 200', () => {
  insomnia.expect(status).to.equal(200);
});

insomnia.test('Ответ — массив', () => {
  insomnia.expect(body).to.be.an('array');
});

insomnia.test('Каждый заказ содержит id и location', () => {
  (body || []).forEach((order) => {
    insomnia.expect(order).to.have.property('id');
    insomnia.expect(order).to.have.property('location');
  });
});

const orderId = insomnia.environment.get('orderId');
if (orderId) {
  insomnia.test('Созданный заказ присутствует в списке активных', () => {
    insomnia.expect((body || []).some((order) => order.id === orderId)).to.be.true;
  });
}

insomnia.test('Статус 200 (заказ завершён) или 409 (заказ ещё не назначен курьеру)', () => {
  insomnia.expect([200, 409]).to.include(insomnia.response.code);
});
